def enabled_state(dump, user):
    lines = dump.splitlines()
    for i, line in enumerate(lines):
        m = re.match(rf'\s*User {user}:', line)
        if m:
            m2 = re.search(r'enabled=(\d+)', line)
            if m2:
                return int(m2.group(1))
            for j in range(i+1, min(i+8, len(lines))):
                m3 = re.search(r'enabled=(\d+)', lines[j])
                if m3:
                    return int(m3.group(1))
                if re.match(r'\s*User \d+:', lines[j]):
                    break
            return None
    return None

